const $ = s => document.querySelector(s);
const NF = new Intl.NumberFormat("id-ID");
const fmt = (v, d=0) => new Intl.NumberFormat("id-ID",{minimumFractionDigits:d,maximumFractionDigits:d}).format(v||0);
const esc = s => String(s==null?"":s).replace(/[&<>"]/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const BULAN = ["Januari","Februari","Maret","April","Mei","Juni","Juli","Agustus","September","Oktober","November","Desember"];
const D0 = Date.UTC(2026,0,1);
const dayOf = s => (Date.UTC(+s.slice(0,4), +s.slice(5,7)-1, +s.slice(8,10)) - D0)/864e5;
const dstr = d => { const t=new Date(D0+d*864e5); return String(t.getUTCDate()).padStart(2,"0")+"-"+String(t.getUTCMonth()+1).padStart(2,"0")+"-"+t.getUTCFullYear(); };
const mOf = d => new Date(D0+d*864e5).getUTCMonth();

const AREA_COL = {"Area Mendis":"#38bdf8","Area B 80":"#a3e635","Area Pakerin":"#fb923c","Area Selaro":"#f472b6","Area ISP":"#facc15","Area Dayung":"#2dd4bf","Area Bintialo":"#c084fc","Area Ketapat":"#f87171","Area Mekar Sari":"#60a5fa"};
const PAL = ["#cffafe","#67e8f9","#3b82f6","#6d28d9","#c026d3"];
const NODATA = "#94a3b8";
