const B = P.batu;
/* warna & urutan jenis batu = dashboard Batu Split (Splite 10/20 = --s1, Splite 5/7 = --s2, Base Course = --s3) */
const JCOL = B.jenis.map(n=>/10\/20/.test(n) ? "var(--s1)" : /5\/7/.test(n) ? "var(--s2)" : "var(--s3)");
const JORD = B.jenis.map((_,i)=>i).sort((a,b)=>JCOL[a].localeCompare(JCOL[b]));
const JL = () => JORD.map(i=>[B.jenis[i],i]);
const jName = j => String(j).replace("MMJ-","");
const KMT = P.geo.kmt;                                   /* posisi jalan tiap 0,1 KM (dari SHP, chainage) */
const KMAX = P.geo.total;
const SEGK = Object.keys(P.seg).map(Number).sort((a,b)=>a-b);
const SEGMAX = SEGK[SEGK.length-1];
function kmLL(x){                       /* posisi pada jalan untuk KM pecahan (interpolasi antar titik KM) */
  const t = Math.max(0, Math.min(KMT.length-1, x*10)), a = Math.floor(t), b = Math.min(KMT.length-1, a+1), f = t-a;
  const p = KMT[a], q = KMT[b]; return [p[0]+(q[0]-p[0])*f, p[1]+(q[1]-p[1])*f];
}
const BL = () => P.fleets[st.fleet] || P.fleets["14"];   /* pembagian area aktif: 14 / 17 fleet */
const blokOf = km => { const bl = BL(); for(const b of bl) if(km>=b[0] && km<b[1]) return b; return km<0 ? bl[0] : bl[bl.length-1]; };
const segOf = km10 => Math.max(0, Math.min(SEGMAX, Math.floor(km10/10)));
const spMonthName = BULAN[+P.sp.month.slice(5,7)-1] + " " + P.sp.month.slice(0,4);

/* ---------- state ---------- */
const lastM = mOf(dayOf(P.last));
const LAYERS = [["sp","Stockpile & stok","#0f172a"],["kml","Label KM","#ffffff"]];
if(P.pdf) LAYERS.push(["pdf","Peta PDF (izin & kawasan)","#84cc16"]);
let st = {m:String(lastM), mode:"batu", lay:{sp:1,kml:1,pdf:0}, mk:{}, fleet:"14", jenis:B.jenis.map((_,i)=>i), kerja:-1, pdfOp:.6};
try{ const s = JSON.parse(localStorage.getItem("mmjPetaBatu2")||"null"); if(s) st = Object.assign(st, s, {lay:Object.assign(st.lay, s.lay||{})}); }catch(e){}
if(st.mode!=="batu" && st.mode!=="area") st.mode = "batu";
const save = () => { try{ localStorage.setItem("mmjPetaBatu2", JSON.stringify(st)); }catch(e){} };
/* tema sama dengan dashboard gabungan lain (kunci dashTheme3) */
const applyTheme = t => { if(t==="dark") document.documentElement.setAttribute("data-theme","dark"); else document.documentElement.removeAttribute("data-theme"); $("#btnTheme").textContent = "Tema: " + (t==="dark" ? "gelap" : "terang"); };
let theme = "light"; try{ theme = localStorage.getItem("mmjTheme")||localStorage.getItem("dashTheme3") || "light"; }catch(e){} applyTheme(theme);

/* ---------- kontrol ---------- */
const months = [...new Set(B.rows.map(r=>mOf(r[0])))].sort((a,b)=>a-b);
$("#fBulan").innerHTML = `<option value="all">Semua (${BULAN[months[0]]} – ${BULAN[months[months.length-1]]} 2026)</option>` + months.map(m=>`<option value="${m}">${BULAN[m]} 2026${m===lastM?" (berjalan)":""}</option>`).join("");
if(![...$("#fBulan").options].some(o=>o.value===st.m)) st.m = String(lastM);
$("#fJenis").innerHTML = JL().map(([j,i])=>`<button class="chip" type="button" data-v="${i}"><i style="background:${JCOL[i]}"></i>${esc(jName(j))}</button>`).join("");
$("#fKerja").innerHTML = `<option value="-1">Semua pekerjaan</option>` + B.kerja.map((k,i)=>k==="(kosong)"?"":`<option value="${i}">${esc(k)}</option>`).join("");
$("#fLay").innerHTML = LAYERS.map(l=>`<button class="chip" type="button" data-v="${l[0]}"><i style="background:${l[2]};border:1px solid rgba(0,0,0,.25)"></i>${l[1]}</button>`).join("");
if(!P.pdf) $("#pdfRow").remove();
$("#spMonth").textContent = "· Daily Summary " + spMonthName;

function syncControls(){
  $("#fBulan").value = st.m; $("#fKerja").value = String(st.kerja);
  document.querySelectorAll("#fMode button").forEach(b=>b.setAttribute("aria-pressed", String(b.dataset.v===st.mode)));
  document.querySelectorAll("#fFleet button").forEach(b=>b.setAttribute("aria-pressed", String(b.dataset.v===st.fleet)));
  document.querySelectorAll("#fJenis button").forEach(b=>b.setAttribute("aria-pressed", String(st.jenis.includes(+b.dataset.v))));
  document.querySelectorAll("#fLay button").forEach(b=>b.setAttribute("aria-pressed", String(!!st.lay[b.dataset.v])));
  document.querySelectorAll("#fMark button").forEach(b=>b.setAttribute("aria-pressed", String(!!st.mk[b.dataset.v])));
  if($("#fPdfOp")){ $("#fPdfOp").value = st.pdfOp; $("#pdfRow").style.display = st.lay.pdf ? "" : "none"; }
}
const on = (sel, ev, fn) => $(sel).addEventListener(ev, fn);
on("#fMode","click",e=>{ const b=e.target.closest("button"); if(!b) return; st.mode=b.dataset.v; render(); });
on("#fFleet","click",e=>{ const b=e.target.closest("button"); if(!b) return; st.fleet=b.dataset.v; if(sel && sel.t==="area") closeCard(); render(); });
on("#fBulan","change",e=>{ st.m=e.target.value; render(); });
on("#fKerja","change",e=>{ st.kerja=+e.target.value; render(); });
on("#fJenis","click",e=>{ const b=e.target.closest("button"); if(!b) return; const v=+b.dataset.v; st.jenis = st.jenis.includes(v) ? st.jenis.filter(x=>x!==v) : st.jenis.concat(v); if(!st.jenis.length) st.jenis=[v]; render(); });
on("#fLay","click",e=>{ const b=e.target.closest("button"); if(!b) return; st.lay[b.dataset.v] = st.lay[b.dataset.v] ? 0 : 1; render(); });
if($("#fPdfOp")) on("#fPdfOp","input",e=>{ st.pdfOp=+e.target.value; if(L_pdf) L_pdf.setOpacity(st.pdfOp); save(); });
on("#btnTheme","click",()=>{ theme = theme==="dark" ? "light" : "dark"; applyTheme(theme); try{ localStorage.setItem("mmjTheme",theme); }catch(e){} });   /* teks persis ini diganti build situs (patch_cmp) -> kunci mmjTheme */
